/** Independent, read-only challenges against original native candidate output. */
import {test, expect} from 'bun:test'
import {pathToFileURL} from 'node:url'
const root=process.env.M73_ACCOUNTING_CANDIDATE ?? 'C:/Users/nimab/.codex/worktrees/4441/Neuvetra'
const moduleAt=(p:string)=>import(pathToFileURL(root+'/'+p).href)
const {validateM73Save,m73SourceChoices,m73ResolveBinding,deriveM73Findings,m73CanonicalJson}=await moduleAt('packages/neuvetra-database/src/m73-validation.ts')
const {decodeGasRegister,decodeGasVersion,decodeGasReport}=await moduleAt('apps/site-web/src/lib/m73-api.ts')
const {m73RenderReport,m73ReportSnapshot}=await moduleAt('packages/neuvetra-database/src/m73-report.ts')
const fixture=await Bun.file(process.env.M73_ACCOUNTING_FIXTURE ?? root+'/.tmp/m73-native-fixture.json').json()
const versions=fixture.register.worksheets.flatMap((w:any)=>w.versions)
const first=versions.find((v:any)=>v.activity.quantityMmbtu==='1250.125')
const request=()=>({...structuredClone(first.activity),expectedVersionId:null,expectedVersionSha256:null,correctionReason:null,idempotencyKey:crypto.randomUUID()})

test('independent native saved register and report pass actual frontend decoders',async()=>{
 await decodeGasRegister(fixture.register,fixture.companyId)
 await decodeGasReport(fixture.originalReport,fixture.companyId,first)
 expect(m73RenderReport(m73ReportSnapshot(first,null))).toBe(fixture.originalReport.html)
})

test('independent invalid quantity/unit/fuel/heat/period and evidence challenges',()=>{
 const cases=[{unit:'therm'},{unit:'scf'},{unit:'kg'},{heatBasis:'LHV'},{fuel:'Renewable Natural Gas'},
 {period:{start:'2025-02-01',endExclusive:'2026-01-01'}},{period:{start:'2026-01-01',endExclusive:'2027-01-01'}},
 {quantityMmbtu:-1},{quantityMmbtu:'-1'},{quantityMmbtu:'1e3'},{quantityMmbtu:'NaN'},
 {quantityMmbtu:'0.0001'},{quantityMmbtu:'1000000000000.000'},{statement:null},{manualConfirmation:false},
 {statement:{...first.activity.statement,consumptionBasis:'purchased'}},
 {statement:{...first.activity.statement,consumptionBasis:'shared_meter'}},
 {quantityMmbtu:'1500.125',discrepancyReason:null}]
 for(const change of cases)expect(()=>validateM73Save({...request(),...change})).toThrow()
})

test('independent missing, evidenced zero and open-discrepancy distinctions',()=>{
 const missing=validateM73Save({...request(),quantityMmbtu:null,statement:null,manualConfirmation:false})
 expect(deriveM73Findings(missing).some((f:any)=>f.code==='activity_missing')).toBe(true)
 const zero={...request(),quantityMmbtu:'0.000',statement:{...first.activity.statement,statedQuantityMmbtu:'0.000'},zeroReason:'Synthetic dedicated meter records no consumption.'}
 expect(validateM73Save(zero).quantityMmbtu).toBe('0.000')
 expect(()=>validateM73Save({...zero,zeroReason:null})).toThrow()
 expect(()=>validateM73Save({...zero,statement:first.activity.statement})).toThrow()
 const discrepant=validateM73Save({...request(),quantityMmbtu:'1500.125',discrepancyReason:'Entered meter reading correction remains unresolved.'})
 expect(deriveM73Findings(discrepant).some((f:any)=>f.code==='activity_statement_discrepancy')).toBe(true)
})

test('independent saved-source boundary and trusted-reference challenges',()=>{
 const sourceId=first.activity.binding.sourceId
 const eligible=(v:any)=>m73SourceChoices(v).find((s:any)=>s.binding.sourceId===sourceId)?.eligible
 expect(eligible(first.coverageVersion)).toBe(true)
 const mutations=[
  (s:any)=>{s.consolidationApproach='equity_share'},
  (s:any)=>{s.sources.find((x:any)=>x.id===sourceId).domain='purchased_electricity'},
  (s:any)=>{s.sources.find((x:any)=>x.id===sourceId).start='2025-02-01'},
  (s:any)=>{s.facilities.find((x:any)=>x.id===first.activity.binding.facilityId).regionCode='NV'},
  (s:any)=>{s.entities.find((x:any)=>x.id===first.activity.binding.entityId).countryCode='CA'},
  (s:any)=>{s.boundaryDecisions.find((x:any)=>x.id===first.activity.binding.boundaryDecisionId).disposition='excluded'},
  (s:any)=>{s.boundaryDecisions.find((x:any)=>x.id===first.activity.binding.boundaryDecisionId).reason=null},
  (s:any)=>{s.boundaryDecisions.find((x:any)=>x.id===first.activity.binding.boundaryDecisionId).evidenceRefs=[]},
  (s:any)=>{s.boundaryDecisions.find((x:any)=>x.id===first.activity.binding.boundaryDecisionId).evidenceRefs[0].expectedSha256='0'.repeat(64)},
 ]
 for(const mutate of mutations){const v=structuredClone(first.coverageVersion);mutate(v.snapshot);expect(eligible(v)).not.toBe(true)}
 for(const field of ['coverageVersionId','coverageVersionSha256','entityId','facilityId','sourceId','boundaryDecisionId']){
  const b={...first.activity.binding,[field]:field.endsWith('Sha256')?'0'.repeat(64):crypto.randomUUID()}
  expect(()=>m73ResolveBinding(b,first.coverageVersion)).toThrow()
 }
})

test('independent duplicate source register and unsupported release claims rejected by actual decoder',async()=>{
 const duplicate=structuredClone(fixture.register);duplicate.worksheets.push(duplicate.worksheets[0])
 await expect(decodeGasRegister(duplicate,fixture.companyId)).rejects.toThrow()
 for(const field of ['scope1Completeness','corporateCompleteness','releaseEligible','assurance']){
  const v=structuredClone(first);v[field]=field==='releaseEligible'?true:field==='assurance'?'assured':'complete'
  await expect(decodeGasVersion(v,fixture.companyId)).rejects.toThrow()
 }
 const fake=structuredClone(first);fake.statement.text+='Unbound statement claim';fake.statement.byteLength=new TextEncoder().encode(fake.statement.text).length;fake.statement.sha256=new Bun.CryptoHasher('sha256').update(fake.statement.text).digest('hex')
 await expect(decodeGasVersion(fake,fixture.companyId)).rejects.toThrow()
})

import {test,expect} from 'bun:test'
import {readM73Journal,validateM73JourneyRoute} from '../../tools/staging/check-m73-hosted'
import {m73CanonicalJson} from '../../packages/neuvetra-database/src/index'

const company='73000000-0000-4000-8000-000000000001',host='https://www.neuvetra.ai',hash=(v:string)=>new Bun.CryptoHasher('sha256').update(v).digest('hex')
function event(sequence:number,previousSha256:string|null,kind:string,data:unknown){const payload={sequence,previousSha256,workspaceId:company,mode:'baseline' as const,kind,data,createdAt:`2026-09-15T16:00:0${sequence}.000Z`};return {...payload,sha256:hash(m73CanonicalJson(payload))}}

test('journal rejects truncation, reordering, cross-workspace substitution and rehashed predecessor breaks',()=>{
 const first=event(1,null,'attempt_started',{mode:'baseline'}),second=event(2,first.sha256,'actual_readiness',{schemaVersion:15}),text=JSON.stringify(first)+'\n'+JSON.stringify(second)+'\n'
 expect(readM73Journal(text,company)).toHaveLength(2)
 for(const changed of [text.slice(0,-1),JSON.stringify(second)+'\n'+JSON.stringify(first)+'\n',text.replace(company,'73000000-0000-4000-8000-000000000099'),JSON.stringify(first)+'\n'+JSON.stringify(event(2,'0'.repeat(64),'actual_readiness',{schemaVersion:15}))+'\n'])expect(()=>readM73Journal(changed,company)).toThrow('Bounded M73 journey refused.')
})

test('network boundary rejects encoded path/query/credential/port and nonworkflow mutations',()=>{
 validateM73JourneyRoute(host+`/workspace-api/workspace/${company}/stationary-natural-gas`,'GET',company)
 for(const [url,method] of [[host+`/workspace-api/workspace/${company}/%2e%2e/session`,'GET'],[host+`/workspace-api/workspace/${company}/stationary-natural-gas?debug=1`,'GET'],['https://user@www.neuvetra.ai/ready','GET'],['https://www.neuvetra.ai:444/ready','GET'],[host+`/workspace-api/workspace/${company}/members`,'POST'],['https://icockcoguyadhryzydvl.supabase.co/auth/v1/logout?scope=global','POST']])expect(()=>validateM73JourneyRoute(url,method,company)).toThrow('Bounded M73 journey refused.')
})

/** Independent read-only reconstruction of the restored schema15 application archive. */
import {test,expect} from 'bun:test'
import {createPostgresConnection,HostedWorkspaceDatabase,readMigrationManifest,m73CanonicalJson,type WorkspaceConnection} from '../../packages/neuvetra-database/src/index'
import {inventory} from '../../tools/staging/m73-common'

const target=process.env.M73_RECOVERY_DATABASE_URL
if(target){const u=new URL(target);if(u.hostname!=='127.0.0.1'||u.port!=='55472'||u.pathname!=='/m73_qa_recovery_20260915_1624'||u.username!=='supabase_admin'||u.password||u.hash)throw Error('M73 recovery review is pinned to the read-only restored clone.')}
const native=target?test:test.skip,sha=(bytes:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(bytes).digest('hex')

native('restricted runtime reconstructs exact M64-M71 records and downloads from restored schema15',async()=>{
 const receipt=JSON.parse(await Bun.file('.superpowers/m73-restore-receipt.json').text())
 const adminUrl=new URL(target!);adminUrl.searchParams.set('options','-cdefault_transaction_read_only=on')
 const admin=createPostgresConnection(adminUrl.toString(),{tls:false,maxConnections:1})
 let actor='',company=''
 try{
  const manifest=await readMigrationManifest(),receipts=(await admin.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows;expect(receipts).toEqual(manifest.slice(0,15).map(({name,sha256})=>({name,sha256})))
  expect((await admin.query<{count:string}>("select count(*)::text count from pg_tables where schemaname='neuvetra' and tablename like 'stationary_gas_%'")).rows[0]?.count).toBe('0')
  const subject=(await admin.query<{user_id:string;company_id:string}>("select a.user_id,a.company_id from neuvetra.staging_access a join neuvetra.company_members m using(company_id,user_id) where a.active and m.role='owner' order by a.user_id limit 1")).rows[0];expect(subject).toBeDefined();actor=subject!.user_id;company=subject!.company_id
  const role=(await admin.query<{safe:boolean}>("select not rolsuper and not rolbypassrls and not rolcreatedb and not rolcreaterole and not rolreplication and not rolinherit and not exists(select 1 from pg_auth_members where member=r.oid) safe from pg_roles r where rolname='neuvetra_runtime'")).rows[0];expect(role?.safe).toBe(true)
  const tables=(await admin.query<{total:string;forced:string}>("select count(*)::text total,count(*) filter(where c.relrowsecurity and c.relforcerowsecurity)::text forced from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and c.relkind='r'")).rows[0];expect(tables).toEqual({total:'67',forced:'67'})
  expect((await admin.query<{unsafe:string}>("select count(*)::text unsafe from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and c.relkind='r' and has_table_privilege('neuvetra_runtime',c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')")).rows[0]?.unsafe).toBe('0')
  expect(await inventory(admin)).toEqual(receipt.inventory)
 }finally{await admin.close()}

 // Reader integrity checks intentionally take SELECT ... FOR SHARE locks; runtime has no DML grants.
 const runtimeUrl=new URL(target!);runtimeUrl.username='neuvetra_runtime'
 const connection=createPostgresConnection(runtimeUrl.toString(),{tls:false,maxConnections:1}),database=new(HostedWorkspaceDatabase as unknown as new(c:WorkspaceConnection,r:string)=>HostedWorkspaceDatabase)(connection,'icockcoguyadhryzydvl')
 try{
  const workspace=await database.findStagingWorkspaceForUser(actor);expect(workspace?.workspace.id).toBe(company);expect(workspace?.role).toBe('owner')
  const manual=await database.findElectricityWorksheet(actor,company);expect(manual?.versions.length).toBe(4)
  const manualReports=await database.findWorksheetReports(actor,company);expect(manualReports?.reports.length).toBe(2)
  const sources=await database.findElectricitySources(actor,company);expect(sources?.sources.length).toBe(2)
  const sourceWorksheet=await database.findSourceElectricityWorksheet(actor,company);expect(sourceWorksheet?.versions.length).toBe(3)
  const sourceReports=await database.findSourceWorksheetReports(actor,company);expect(sourceReports?.reports.length).toBe(3)
  const annual=await database.findAnnualElectricityWorksheet(actor,company);expect(annual?.versions.length).toBe(4)
  const annualReports=await database.findAnnualWorksheetReports(actor,company);expect(annualReports?.reports.length).toBe(3)
  const evidence=await database.findAnnualElectricityEvidence(actor,company);expect(evidence?.versions.length).toBe(4)
  const evidenceReports=await database.findAnnualEvidenceReports(actor,company);expect(evidenceReports?.reports.length).toBe(4)
  const corporate=await database.findCorporateInventory(actor,company);expect(corporate?.versions.length).toBe(2);expect(corporate?.headVersionId).toBe(corporate?.versions.at(-1)?.id)

  const downloads:{kind:string;id:string;sha256:string;bytes:number}[]=[]
  for(const source of sources!.sources){const found=await database.downloadElectricitySource(actor,company,source.id);expect(found?.source.sha256).toBe(source.sha256);expect(sha(found!.bytes)).toBe(source.sha256);downloads.push({kind:'source',id:source.id,sha256:source.sha256,bytes:found!.bytes.byteLength})}
  for(const report of manualReports!.reports){const found=await database.downloadWorksheetReport(actor,company,report.id);expect(sha(found!.bytes)).toBe(report.reportSha256);expect(found!.bytes.byteLength).toBe(report.reportByteLength);downloads.push({kind:'m65-report',id:report.id,sha256:report.reportSha256,bytes:found!.bytes.byteLength})}
  for(const report of sourceReports!.reports){const found=await database.downloadSourceWorksheetReport(actor,company,report.id);expect(sha(found!.bytes)).toBe(report.reportSha256);expect(found!.bytes.byteLength).toBe(report.reportByteLength);downloads.push({kind:'m66-report',id:report.id,sha256:report.reportSha256,bytes:found!.bytes.byteLength})}
  for(const report of annualReports!.reports){const found=await database.downloadAnnualWorksheetReport(actor,company,report.id);expect(sha(found!.bytes)).toBe(report.reportSha256);expect(found!.bytes.byteLength).toBe(report.reportByteLength);downloads.push({kind:'m67-report',id:report.id,sha256:report.reportSha256,bytes:found!.bytes.byteLength})}
  for(const report of evidenceReports!.reports){const found=await database.downloadAnnualEvidenceReport(actor,company,report.id);expect(sha(found!.bytes)).toBe(report.reportSha256);expect(found!.bytes.byteLength).toBe(report.reportByteLength);downloads.push({kind:'m68-report',id:report.id,sha256:report.reportSha256,bytes:found!.bytes.byteLength})}
  console.log(m73CanonicalJson({status:'m73_recovery_runtime_reconstruction_passed',companyId:company,versions:{m64:manual!.versions.length,m66:sourceWorksheet!.versions.length,m67:annual!.versions.length,m68:evidence!.versions.length,m71:corporate!.versions.length},downloads,corporateHeadSha256:corporate!.versions.at(-1)!.versionSha256}))
 }finally{await connection.close()}
 const verify=createPostgresConnection(adminUrl.toString(),{tls:false,maxConnections:1});try{expect(await inventory(verify)).toEqual(receipt.inventory)}finally{await verify.close()}
},120000)

import {test,expect} from 'bun:test'
import {createM73Authority} from '../../apps/site-api/src/calculation/m73-authority'
import {M73_PERIOD,type M73AuthorityInput} from '../../packages/neuvetra-database/src/m73-contract'

const id='11111111-1111-4111-8111-111111111111',hash='1'.repeat(64)
const input:M73AuthorityInput={binding:{coverageVersionId:id,coverageVersionSha256:hash,entityId:id,facilityId:id,sourceId:id,boundaryDecisionId:id},period:M73_PERIOD,fuel:'Natural Gas',heatBasis:'HHV',unit:'MMBtu',quantityMmbtu:'1250.125',statementSha256:hash}

test('authority limits concurrent children, sanitizes failure and releases every slot',async()=>{
 const authority=createM73Authority(),results=await Promise.allSettled([authority.calculate(input),authority.calculate(input),authority.calculate(input)])
 expect(results.filter(x=>x.status==='fulfilled')).toHaveLength(2);expect(results.filter(x=>x.status==='rejected')).toHaveLength(1)
 const rejected=results.find(x=>x.status==='rejected') as PromiseRejectedResult;expect(rejected.reason).toEqual(Error('Natural-gas authority unavailable.'))
 expect((await authority.calculate(input)).total.display).toBe('66399.7643')
 const unavailable=createM73Authority({python:'definitely-missing-m73-python'});await expect(unavailable.calculate(input)).rejects.toEqual(Error('Natural-gas authority unavailable.'))
 expect((await authority.calculate(input)).resultSha256).toMatch(/^[a-f0-9]{64}$/)
})

/** Independent M73 security drill. Opt in only to a fresh m73_security_* local clone. */
import {test,expect} from 'bun:test'
import {createPostgresConnection,HostedWorkspaceDatabase,provisionStagingRoster,createM71Seed,M71_ARTIFACT,M71_EVIDENCE_SHA256,M73_PROFILE,M73_PERIOD,M73_LIMITATIONS,m73SourceChoices,readMigrationManifest,m73CanonicalJson,type WorkspaceConnection,type M73SaveInput,type M73Version} from '../../packages/neuvetra-database/src/index'
import {createM73Routes} from '../../apps/site-api/src/workspace/m73-routes'
import {createM73Authority} from '../../apps/site-api/src/calculation/m73-authority'
import {decodeGasRegister,decodeGasVersion,decodeGasReport} from '../../apps/site-web/src/lib/m73-api'

const target=process.env.M73_SECURITY_DATABASE_URL
if(target){const u=new URL(target);if(u.hostname!=='127.0.0.1'||u.port!=='55463'||!/^\/m73_security_[a-z0-9_]+$/.test(u.pathname)||u.username!=='m63_test_admin'||u.password||u.search||u.hash)throw Error('M73 security tests require an isolated local m73_security_* clone.')}
const native=target?test:test.skip

native('schema 15 recovery applies the exact migration without changing prior rows or runtime posture',async()=>{
 const db=createPostgresConnection(target!,{tls:false,maxConnections:1})
 try{
  const manifest=await readMigrationManifest();expect(manifest).toHaveLength(16);expect(manifest[15]!.sha256).toBe('2f5489d37fdd59963d12e60947b8dddce34cc4e1dc4100813545b1c0dbb1c9b7')
  const rows=async(tx:WorkspaceConnection)=>{const names=(await tx.query<{name:string}>("select tablename name from pg_tables where schemaname='neuvetra' and tablename<>'schema_migrations' and tablename not like 'stationary_gas_%' order by 1")).rows;const result:Record<string,string>={};for(const {name} of names)result[name]=m73CanonicalJson((await tx.query(`select to_jsonb(t) value from neuvetra.${name} t order by to_jsonb(t)::text`)).rows);return result}
  const before=await db.transaction(async tx=>{const receipts=(await tx.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows;expect(receipts).toEqual(manifest.slice(0,15).map(({name,sha256})=>({name,sha256})));return rows(tx)})
  await db.transaction(async tx=>{await tx.exec(manifest[15]!.sql);await tx.query('insert into neuvetra.schema_migrations(name,sha256) values($1,$2)',[manifest[15]!.name,manifest[15]!.sha256])})
  expect(await db.transaction(rows)).toEqual(before)
  const posture=(await db.query<{safe:boolean}>("select not rolsuper and not rolbypassrls and not rolcreatedb and not rolcreaterole and not rolreplication and not rolinherit safe from pg_roles where rolname='neuvetra_runtime'")).rows[0];expect(posture?.safe).toBe(true)
  const secured=(await db.query<{count:string}>("select count(*)::text count from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and c.relname like 'stationary_gas_%' and c.relkind='r' and c.relrowsecurity and c.relforcerowsecurity")).rows[0];expect(secured?.count).toBe('7')
 }finally{await db.close()}
},120000)

native('adversarial tenant, integrity, duplicate-source, report and revocation boundaries',async()=>{
 const company=crypto.randomUUID(),otherCompany=crypto.randomUUID(),users={owner:crypto.randomUUID(),manager:crypto.randomUUID(),reviewer:crypto.randomUUID(),member:crypto.randomUUID(),outsider:crypto.randomUUID()},origin='http://127.0.0.1:37373'
 const operator=createPostgresConnection(target!,{tls:false,maxConnections:3}),runtimeUrl=new URL(target!);runtimeUrl.username='neuvetra_runtime'
 const runtime=createPostgresConnection(runtimeUrl.toString(),{tls:false,maxConnections:4}),database=new(HostedWorkspaceDatabase as unknown as new(c:WorkspaceConnection,r:string)=>HostedWorkspaceDatabase)(runtime,'abcdefghijklmnopqrst'),authority=createM73Authority()
 const route=createM73Routes({database,authority,origin,validateUser:async token=>users[token as keyof typeof users]?{id:users[token as keyof typeof users],email:null,phone:null,fullName:null}:null})
 const request=(suffix='',actor:string|null='owner',body?:unknown)=>route(new Request(origin+`/workspace/${company}/stationary-natural-gas`+suffix,{method:body===undefined?'GET':'POST',headers:{origin,...(actor?{authorization:'Bearer '+actor}:{}),...(body===undefined?{}:{'content-type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)}))
 const ok=async(suffix='',actor='owner',body?:unknown)=>{const response=await request(suffix,actor,body),text=await response.text();expect(response.status,text).toBe(body===undefined?200:201);return JSON.parse(text)}
 try{
  for(const id of Object.values(users))await operator.query('insert into auth.users(id) values($1)',[id])
  await provisionStagingRoster(operator,{expectedProjectRef:'abcdefghijklmnopqrst',workspaceId:company,ownerUserId:users.owner,members:[{userId:users.manager,role:'admin'},{userId:users.reviewer,role:'admin'},{userId:users.member,role:'member'}]})
  await provisionStagingRoster(operator,{expectedProjectRef:'abcdefghijklmnopqrst',workspaceId:otherCompany,ownerUserId:users.outsider,members:[]})
  const coverageSeed=createM71Seed(),sourceId=crypto.randomUUID();coverageSeed.companyLabel='Illustrative security company';coverageSeed.sources.push({id:sourceId,entityId:coverageSeed.entities[0]!.id,facilityId:coverageSeed.facilities[0]!.id,name:'Dedicated boiler A',domain:'stationary_combustion',...M73_PERIOD,evidenceRefs:[]});coverageSeed.coverageItems.push({id:crypto.randomUUID(),entityId:coverageSeed.entities[0]!.id,sourceId,domain:'stationary_combustion',...M73_PERIOD,disposition:'missing',activityDataState:'missing',evidenceState:'missing',methodReadiness:'candidate',reason:null,evidenceRefs:[],estimateBasis:null,quantity:null,unit:null});coverageSeed.boundaryDecisions[0]!.reason='Synthetic operational-control basis';coverageSeed.boundaryDecisions[0]!.evidenceRefs=[{artifactId:M71_ARTIFACT.id,expectedSha256:M71_EVIDENCE_SHA256,locator:M71_ARTIFACT.locator,purpose:'Synthetic control basis'}]
  const coverage=await database.saveCorporateInventory(users.owner,company,null,{snapshot:coverageSeed,expectedVersionId:null,expectedVersionSha256:null,correctionReason:null,idempotencyKey:crypto.randomUUID()}),binding=m73SourceChoices(coverage)[0]!.binding
  const input:M73SaveInput={profile:M73_PROFILE,binding,period:M73_PERIOD,fuel:'Natural Gas',heatBasis:'HHV',unit:'MMBtu',quantityMmbtu:'1250.125',statement:{issuer:'Fictional supplier',reference:'SEC-2025-A',meterLabel:'DEDICATED-A',statedQuantityMmbtu:'1250.125',description:'Synthetic dedicated-meter consumed energy with no adjustments.',consumptionBasis:'dedicated_meter_consumed_no_adjustments'},manualConfirmation:true,discrepancyReason:null,zeroReason:null,expectedVersionId:null,expectedVersionSha256:null,correctionReason:null,idempotencyKey:crypto.randomUUID()}
  expect((await request('',null)).status).toBe(401);expect((await request('','outsider')).status).toBe(404);expect((await request('','member',input)).status).toBe(403)
  console.log('m73_security_stage: admission')
  let version=await decodeGasVersion(await ok('','owner',input),company),worksheet=version.worksheetId
  const reviewInput={versionId:version.id,expectedVersionSha256:version.versionSha256,decision:'accepted_bounded_internal' as const,note:'Independent bounded synthetic review.',acknowledgedLimitations:[...M73_LIMITATIONS],idempotencyKey:crypto.randomUUID()}
  const decision=await ok(`/${worksheet}/reviews`,'reviewer',reviewInput);version={...version,review:decision}
  const reportInput={versionId:version.id,expectedVersionSha256:version.versionSha256,expectedDecisionId:decision.id,expectedDecisionSha256:decision.decisionSha256,idempotencyKey:crypto.randomUUID()}
  expect((await request(`/${worksheet}/reports`,'owner',{...reportInput,expectedDecisionId:null,expectedDecisionSha256:null})).status).toBe(409)
